.extern v_writePSG
.extern v_doSound
.extern currentJoy1X
.extern currentJoy1Y
.extern currentButtonState
.extern currentJoy2X
.extern currentJoy2Y
.extern commonHints
.extern __aeabi_idiv
.extern __aeabi_idivmod
.extern RPI_AuxUartInit
.extern RPI_AuxUartWrite

