@ ================================================================
@ PiTrex ARM32 builtins
@ ================================================================

@ pitrex_wait_recal() — frame sync + force calibrated T1=80
.global pitrex_wait_recal
.type pitrex_wait_recal, %function
pitrex_wait_recal:
    push    {lr}
    bl      v_WaitRecal
    mov     r0, #80
    bl      v_setScale
    ldr     r0, =UART_TRACE_FRAMES_LEFT
    ldr     r1, [r0]
    cmp     r1, #0
    popeq   {pc}
    sub     r1, r1, #1
    str     r1, [r0]
    @ increment frame number, print header
    ldr     r0, =UART_FRAME_NUM
    ldr     r2, [r0]
    add     r2, r2, #1
    str     r2, [r0]
    ldr     r0, =.Lstr_frame_hdr
    bl      vpy_uart_puts       @ ">>> FRAME "
    ldr     r0, =UART_FRAME_NUM
    ldr     r0, [r0]
    bl      vpy_uart_print_int
    ldr     r0, =.Lstr_frame_hdr_end
    bl      vpy_uart_puts       @ " START <<<\r\n"
    pop     {pc}
    .ltorg

@ pitrex_set_intensity(r0=brightness 0-127)
.global pitrex_set_intensity
.type pitrex_set_intensity, %function
pitrex_set_intensity:
    push    {lr}
    bl      v_setBrightness
    pop     {pc}
    .ltorg

@ pitrex_move(r0=x, r1=y) — move beam, no draw
.global pitrex_move
.type pitrex_move, %function
pitrex_move:
    push    {r4, lr}
    mov     r4, #127
    mul     r2, r0, r4          @ r2 = x*127 (Rd≠Rm)
    ldr     r4, =PITREX_CUR_X
    str     r2, [r4]            @ PITREX_CUR_X = x*127
    mov     r4, #127
    mul     r2, r1, r4          @ r2 = y*127 (Rd≠Rm)
    ldr     r4, =PITREX_CUR_Y
    str     r2, [r4]            @ PITREX_CUR_Y = y*127
    bl      v_directMove32
    pop     {r4, pc}
    .ltorg

@ pitrex_draw_line(r0=x0, r1=y0, r2=x1, r3=y1, [sp+0]=brightness)
.global pitrex_draw_line
.type pitrex_draw_line, %function
pitrex_draw_line:
    push    {r4, lr}
    ldr     r4, [sp, #8]        @ brightness
    mov     r12, #127
    mul     r0, r0, r12         @ x0 * 127
    mul     r1, r1, r12         @ y0 * 127
    mul     r2, r2, r12         @ x1 * 127
    mul     r3, r3, r12         @ y1 * 127
    push    {r4}               @ brightness as 5th arg
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r4, pc}
    .ltorg

@ pitrex_draw_line_rel(r0=dx, r1=dy, r2=brightness)
.global pitrex_draw_line_rel
.type pitrex_draw_line_rel, %function
pitrex_draw_line_rel:
    push    {r4, r5, r6, r7, lr}
    mov     r4, #127
    mul     r4, r0, r4          @ r4 = dx * 127
    mov     r5, #127
    mul     r5, r1, r5          @ r5 = dy * 127
    mov     r6, r2              @ r6 = brightness
    ldr     r7, =PITREX_CUR_X
    ldr     r0, [r7]            @ r0 = cur_x
    ldr     r12, =PITREX_CUR_Y
    ldr     r1, [r12]           @ r1 = cur_y
    add     r2, r0, r4          @ r2 = new_x
    add     r3, r1, r5          @ r3 = new_y
    push    {r0, r1, r2, r3}    @ save call args
    mov     r1, r2              @ trace x = new_x
    mov     r2, r3              @ trace y = new_y
    ldr     r0, =.Lstr_dr
    bl      uart_trace_xy
    pop     {r0, r1, r2, r3}
    push    {r6}               @ brightness as 5th arg
    bl      v_directDraw32
    add     sp, sp, #4
    ldr     r1, =PITREX_CUR_X
    ldr     r2, [r1]
    add     r2, r2, r4
    str     r2, [r1]            @ PITREX_CUR_X += dx*100
    ldr     r1, =PITREX_CUR_Y
    ldr     r2, [r1]
    add     r2, r2, r5
    str     r2, [r1]            @ PITREX_CUR_Y += dy*100
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_draw_vector(r0=asset_ptr, r1=ox, r2=oy)
.global pitrex_draw_vector
.type pitrex_draw_vector, %function
pitrex_draw_vector:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}
    push    {r1, r2}            @ [sp+0]=ox [sp+4]=oy (raw VPy units)
    mov     r4, r0              @ asset header ptr
    mov     r3, #127
    mul     r6, r1, r3          @ r6 = ox*127 (Rd=r6 ≠ Rm=r1)
    mul     r7, r2, r3          @ r7 = oy*127 (Rd=r7 ≠ Rm=r2)
    ldr     r5, [r4], #4        @ path_count
    mov     r8, #0
dv_path_loop:
    cmp     r8, r5
    bge     dv_done
    ldr     r9, [r4], #4        @ r9 = path data ptr
    ldrb    r10, [r9], #1       @ r10 = path intensity (from .vec)
    ldrsb   r1, [r9], #1        @ r1 = y_start (i8)
    ldrsb   r0, [r9], #1        @ r0 = x_start (i8)
    add     r9, r9, #2          @ skip 2 hdr padding bytes
    mov     r3, #127
    mul     r2, r0, r3          @ r2 = x_start*127 (Rd=r2 ≠ Rm=r0)
    add     r0, r2, r6          @ r0 = (x_start+ox)*127
    mul     r2, r1, r3          @ r2 = y_start*127 (Rd=r2 ≠ Rm=r1)
    add     r1, r2, r7          @ r1 = (y_start+oy)*127
    ldr     r2, =PITREX_CUR_X
    str     r0, [r2]            @ PITREX_CUR_X = target_x
    ldr     r2, =PITREX_CUR_Y
    str     r1, [r2]            @ PITREX_CUR_Y = target_y
    push    {r0, r1}            @ save call args
    mov     r2, r1              @ trace y
    mov     r1, r0              @ trace x
    ldr     r0, =.Lstr_mv
    bl      uart_trace_xy
    pop     {r0, r1}
    bl      v_directMove32
    mov     r0, #80
    bl      v_setScale
    b       dv_after_pool
    .ltorg
dv_after_pool:
dv_seg_loop:
    ldrb    r0, [r9], #1        @ marker (0xFE=bezier, 0xFF=line, 0x02=end)
    cmp     r0, #2
    beq     dv_seg_done
    cmp     r0, #0xFE
    beq     dv_bezier_seg
    ldrsb   r1, [r9], #1        @ dy
    ldrsb   r0, [r9], #1        @ dx
    mov     r2, r10             @ intensity from .vec
    push    {r4, r5, r6, r7, r8, r9, r10}
    bl      pitrex_draw_line_rel
    pop     {r4, r5, r6, r7, r8, r9, r10}
    b       dv_seg_loop
dv_seg_done:
    add     r8, r8, #1
    b       dv_path_loop
dv_bezier_seg:
    push    {r4, r5, r6, r7, r8, r9, r10}
    sub     sp, sp, #24
    ldr     r4, [sp, #52]        @ r4 = raw ox (VPy units)
    ldr     r5, [sp, #56]        @ r5 = raw oy (VPy units)
    ldrsb   r6, [r9], #1
    add     r0, r6, r4
    ldrsb   r6, [r9], #1
    add     r1, r6, r5
    ldrsb   r6, [r9], #1
    add     r2, r6, r4
    ldrsb   r6, [r9], #1
    add     r3, r6, r5
    ldrsb   r6, [r9], #1
    add     r7, r6, r4
    str     r7, [sp, #0]
    ldrsb   r6, [r9], #1
    add     r7, r6, r5
    str     r7, [sp, #4]
    ldrsb   r6, [r9], #1
    add     r7, r6, r4
    str     r7, [sp, #8]
    ldrsb   r6, [r9], #1
    add     r7, r6, r5
    str     r7, [sp, #12]
    mov     r6, #16
    str     r6, [sp, #16]
    ldr     r6, [sp, #48]
    uxtb    r6, r6
    str     r6, [sp, #20]
    str     r9, [sp, #44]
    bl      v_drawBezierCubic
    add     sp, sp, #24
    pop     {r4, r5, r6, r7, r8, r9, r10}
    b       dv_seg_loop
dv_done:
    add     sp, sp, #8          @ remove saved raw ox, oy
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

@ pitrex_draw_vector_ex(r0=asset_ptr, r1=ox, r2=oy, r3=mirror, [sp]=intensity_unused)
.global pitrex_draw_vector_ex
.type pitrex_draw_vector_ex, %function
pitrex_draw_vector_ex:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}  @ 32 bytes
    mov     r4, r0              @ asset header ptr
    mov     r5, r1              @ ox
    mov     r6, r2              @ oy
    mov     r7, r3              @ mirror flag
    ldr     r9, [r4], #4        @ path_count
    push    {r9}                @ [sp+0] = path_count
    mov     r9, #0
    push    {r9}                @ [sp+0] = path_idx, [sp+4] = path_count
dvex_path_loop:
    ldr     r0, [sp]            @ path_idx
    ldr     r1, [sp, #4]        @ path_count
    cmp     r0, r1
    bge     dvex_done
    ldr     r9, [r4], #4        @ r9 = path data ptr
    ldrb    r10, [r9], #1       @ r10 = path intensity (from .vec)
    ldrsb   r1, [r9], #1        @ r1 = y_start (i8)
    ldrsb   r0, [r9], #1        @ r0 = x_start (i8)
    add     r9, r9, #2          @ skip 2 hdr padding bytes
    cmp     r7, #1
    it      eq
    rsbeq   r0, r0, #0          @ mirror x_start
    mov     r12, #127
    mul     r2, r0, r12         @ r2 = x_start*127 (Rd=r2 ≠ Rm=r0)
    mul     r3, r5, r12         @ r3 = ox*127     (Rd=r3 ≠ Rm=r5)
    add     r0, r2, r3          @ r0 = (x_start+ox)*127
    mul     r2, r1, r12         @ r2 = y_start*127 (Rd=r2 ≠ Rm=r1)
    mul     r3, r6, r12         @ r3 = oy*127     (Rd=r3 ≠ Rm=r6)
    add     r1, r2, r3          @ r1 = (y_start+oy)*127
    ldr     r2, =PITREX_CUR_X
    str     r0, [r2]            @ PITREX_CUR_X = target_x
    ldr     r2, =PITREX_CUR_Y
    str     r1, [r2]            @ PITREX_CUR_Y = target_y
    push    {r0, r1}            @ save call args
    mov     r2, r1              @ trace y
    mov     r1, r0              @ trace x
    ldr     r0, =.Lstr_mv
    bl      uart_trace_xy
    pop     {r0, r1}
    bl      v_directMove32
    mov     r0, #80
    bl      v_setScale
dvex_seg_loop:
    ldrb    r0, [r9], #1
    cmp     r0, #2
    beq     dvex_seg_done
    cmp     r0, #0xFE
    beq     dvex_bezier_seg
    ldrsb   r1, [r9], #1        @ dy
    ldrsb   r0, [r9], #1        @ dx
    cmp     r7, #1
    it      eq
    rsbeq   r0, r0, #0
    mov     r2, r10             @ intensity from .vec
    push    {r4, r5, r6, r7, r9, r10}
    bl      pitrex_draw_line_rel
    pop     {r4, r5, r6, r7, r9, r10}
    b       dvex_seg_loop
dvex_seg_done:
    ldr     r0, [sp]
    add     r0, r0, #1
    str     r0, [sp]            @ path_idx++
    b       dvex_path_loop
dvex_bezier_seg:
    push    {r4, r5, r6, r7, r9, r10}
    sub     sp, sp, #24
    ldr     r4, [sp, #28]        @ r4 = ox (raw VPy units)
    ldr     r5, [sp, #32]        @ r5 = oy (raw VPy units)
    ldr     r12, [sp, #36]       @ r12 = mirror flag
    ldrsb   r6, [r9], #1
    add     r0, r6, r4
    cmp     r12, #1
    it      eq
    rsbeq   r0, r0, #0
    ldrsb   r6, [r9], #1
    add     r1, r6, r5
    ldrsb   r6, [r9], #1
    add     r2, r6, r4
    cmp     r12, #1
    it      eq
    rsbeq   r2, r2, #0
    ldrsb   r6, [r9], #1
    add     r3, r6, r5
    ldrsb   r6, [r9], #1
    add     r6, r6, r4
    cmp     r12, #1
    it      eq
    rsbeq   r6, r6, #0
    str     r6, [sp, #0]
    ldrsb   r6, [r9], #1
    add     r6, r6, r5
    str     r6, [sp, #4]
    ldrsb   r6, [r9], #1
    add     r6, r6, r4
    cmp     r12, #1
    it      eq
    rsbeq   r6, r6, #0
    str     r6, [sp, #8]
    ldrsb   r6, [r9], #1
    add     r6, r6, r5
    str     r6, [sp, #12]
    mov     r6, #16
    str     r6, [sp, #16]
    ldr     r6, [sp, #44]
    uxtb    r6, r6
    str     r6, [sp, #20]
    str     r9, [sp, #40]
    bl      v_drawBezierCubic
    add     sp, sp, #24
    pop     {r4, r5, r6, r7, r9, r10}
    b       dvex_seg_loop
dvex_done:
    add     sp, sp, #8          @ pop path_idx + path_count
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

@ pitrex_j1_x() → r0 = X axis (-127..127)
.global pitrex_j1_x
.type pitrex_j1_x, %function
pitrex_j1_x:
    ldr     r1, =currentJoy1X
    ldrsb   r0, [r1]
    bx      lr
    .ltorg

@ pitrex_j1_y() → r0 = Y axis (-127..127)
.global pitrex_j1_y
.type pitrex_j1_y, %function
