@ Newlib syscall stubs (_kill, _getpid)
.global _kill
.type _kill, %function
_kill:
    bx      lr

.global _getpid
.type _getpid, %function
_getpid:
    mov     r0, #1
    bx      lr

@ pitrex_play_music(r0=music_base)
.global pitrex_play_music
.type pitrex_play_music, %function
pitrex_play_music:
    ldr     r1, =PSG_MUSIC_START
    str     r0, [r1]
    add     r2, r0, #8          @ first event = base + 8
    ldr     r1, =PSG_MUSIC_PTR
    str     r2, [r1]
    ldr     r1, =PSG_IS_PLAYING
    mov     r0, #1
    str     r0, [r1]
    ldr     r1, =PSG_DELAY_FRAMES
    mov     r0, #0
    str     r0, [r1]
    bx      lr
    .ltorg

@ pitrex_stop_music()
.global pitrex_stop_music
.type pitrex_stop_music, %function
pitrex_stop_music:
    push    {lr}
    ldr     r1, =PSG_IS_PLAYING
    mov     r0, #0
    str     r0, [r1]
    mov     r0, #8
    mov     r1, #0
    bl      v_writePSG
    mov     r0, #9
    mov     r1, #0
    bl      v_writePSG
    mov     r0, #10
   mov     r1, #0
    bl      v_writePSG
    mov     r0, #7
    mov     r1, #0x3F
 bl      v_writePSG
    pop     {pc}
    .ltorg

@ pitrex_music_update() — advance music sequencer one frame
.global pitrex_music_update
.type pitrex_music_update, %function
pitrex_music_update:
    push    {r4, r5, r6, r7, lr}
    ldr     r0, =PSG_IS_PLAYING
    ldr     r0, [r0]
    cmp     r0, #0
    beq     pmu_done
    ldr     r4, =PSG_DELAY_FRAMES
    ldr     r0, [r4]
    cmp     r0, #0
    beq     pmu_process
    sub     r0, r0, #1
    str     r0, [r4]
    b       pmu_done
pmu_process:
    ldr     r5, =PSG_MUSIC_PTR
    ldr     r5, [r5]    @ event ptr
    ldrb    r6, [r5, #1]                @ num_writes
    cmp     r6, #0
    beq     pmu_end
    cmp     r6, #0xFF
 beq     pmu_loop
    add     r7, r5, #2
pmu_wl:
    cmp     r6, #0
    beq     pmu_after
    ldrb    r0, [r7]
    ldrb    r1, [r7, #1]
    push    {r6, r7}
    bl      v_writePSG
    pop     {r6, r7}
    add     r7, r7, #2
    sub     r6, r6, #1
    b       pmu_wl
pmu_after:
    ldr     r0, =PSG_MUSIC_PTR
    str     r7, [r0]
    ldrb    r0, [r7]                    @ next event delay
    str     r0, [r4]
    b       pmu_done
pmu_end:
    bl      pitrex_stop_music
    b       pmu_done
pmu_loop:
    ldr     r0, =PSG_MUSIC_START
    ldr     r0, [r0]
    ldr     r1, [r0, #4]                @ loop_event_byte_offset
    add     r1, r0, r1
    ldr     r0, =PSG_MUSIC_PTR
    str     r1, [r0]
    ldrb    r0, [r1]
    str     r0, [r4]
pmu_done:
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_play_sfx(r0=sfx_base)
.global pitrex_play_sfx
.type pitrex_play_sfx, %function
pitrex_play_sfx:
    add     r0, r0, #4
    ldr     r1, =PSG_SFX_PTR
    str     r0, [r1]
    ldr     r1, =PSG_SFX_ACTIVE
    mov     r0, #1
    str     r0, [r1]
    ldr     r1, =PSG_SFX_DELAY
    mov     r0, #0
    str     r0, [r1]
    bx      lr
    .ltorg

@ pitrex_load_level(r0=level_ptr) — initialise level runtime state
.global pitrex_load_level
.type pitrex_load_level, %function
pitrex_load_level:
    push    {r4, r5, r6, r7, lr}
    mov     r4, r0              @ r4 = level_ptr
    ldr     r1, =LEVEL_DATA_PTR
    str     r4, [r1]
    ldrb    r5, [r4, #9]        @ r5 = gpCount
    cmp     r5, #32
    movgt   r5, #32
    ldr     r1, =LEVEL_GP_COUNT
    str     r5, [r1]
    ldr     r6, [r4, #16]       @ r6 = gpObjectsPtr
    ldr     r7, =LEVEL_GP_BUF
    cmp     r5, #0
    beq     .Lll_done
.Lll_copy:
    ldrsh   r0, [r6]            @ x (offset 0)
    ldrsh   r1, [r6, #2]        @ y (offset 2)
    ldrsb   r2, [r6, #14]       @ vel_x_init (offset 14)
    ldrsb   r3, [r6, #15]       @ vel_y_init (offset 15)
    strh    r0, [r7]            @ buf.x
    strh    r1, [r7, #2]        @ buf.y
    strh    r2, [r7, #4]        @ buf.vx
    strh    r3, [r7, #6]        @ buf.vy
    add     r6, r6, #20         @ advance ROM obj ptr (20 bytes)
    add     r7, r7, #8          @ advance buf ptr
    subs    r5, r5, #1
    bne     .Lll_copy
.Lll_done:
    ldrsh   r0, [r4, #24]       @ scrollLimit left
    ldr     r1, =SCROLL_LIMIT_LEFT
    str     r0, [r1]
    ldrsh   r0, [r4, #26]       @ scrollLimit right
    ldr     r1, =SCROLL_LIMIT_RIGHT
    str     r0, [r1]
    ldrsh   r0, [r4, #28]       @ scrollLimit top
    ldr     r1, =SCROLL_LIMIT_TOP
    str     r0, [r1]
    ldrsh   r0, [r4, #30]       @ scrollLimit bottom
    ldr     r1, =SCROLL_LIMIT_BOTTOM
    str     r0, [r1]
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_show_level() — draw all level objects (BG+GP+FG)
.global pitrex_show_level
.type pitrex_show_level, %function
pitrex_show_level:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    ldr     r9, =LEVEL_DATA_PTR
    ldr     r9, [r9]            @ r9 = header ptr
    cmp     r9, #0
    beq     .Lshl_done
    ldr     r10, =CAMERA_X
    ldr     r10, [r10]          @ r10 = cam_x
    ldr     r11, =CAMERA_Y
    ldr     r11, [r11]          @ r11 = cam_y
    @ --- BG layer ---
    ldrb    r4, [r9, #8]        @ bgCount
    ldr     r5, [r9, #12]       @ bgObjectsPtr
    cmp     r4, #0
    beq     .Lshl_gp
.Lshl_bg:
    ldrsh   r0, [r5]            @ obj.x
    ldrsh   r1, [r5, #2]        @ obj.y
    ldrb    r8, [r5, #5]        @ intensity
    ldr     r6, [r5, #8]        @ vector_ptr
    sub     r0, r0, r10         @ ox = x - cam_x
    sub     r1, r1, r11         @ oy = y - cam_y
    @ Cull: skip if |ox| > 180 (fully off-screen)
    mov     r12, r0
    cmp     r12, #0
    it      lt
    rsblt   r12, r12, #0        @ r12 = |ox|
    cmp     r12, #180
    bgt     .Lshl_bg_skip
    push    {r4, r5, r10, r11}  @ save loop state
    push    {r8}                @ 5th arg: intensity
    mov     r3, #0              @ mirror=0
    mov     r2, r1              @ oy
    mov     r1, r0              @ ox
    mov     r0, r6              @ asset_ptr
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4          @ pop intensity
    pop     {r4, r5, r10, r11}
.Lshl_bg_skip:
    add     r5, r5, #20         @ next BG object (20 bytes)
    subs    r4, r4, #1
    bne     .Lshl_bg
.Lshl_gp:
    @ --- GP layer (mutable positions) ---
    ldr     r4, =LEVEL_GP_COUNT
    ldr     r4, [r4]            @ gpCount
    ldr     r5, [r9, #16]       @ gpObjectsPtr (ROM, for vec_ptr+intensity)
    ldr     r7, =LEVEL_GP_BUF   @ buf (current x,y)
    cmp     r4, #0
    beq     .Lshl_fg
.Lshl_gp_loop:
    ldrsh   r0, [r7]            @ buf.x
    ldrsh   r1, [r7, #2]        @ buf.y
    ldrb    r8, [r5, #5]        @ intensity (from ROM obj)
    ldr     r6, [r5, #8]        @ vector_ptr (from ROM obj)
    sub     r0, r0, r10         @ ox = x - cam_x
    sub     r1, r1, r11         @ oy = y - cam_y
    @ Cull: skip if |ox| > 180 (fully off-screen)
    mov     r12, r0
    cmp     r12, #0
    it      lt
    rsblt   r12, r12, #0        @ r12 = |ox|
    cmp     r12, #180
    bgt     .Lshl_gp_skip
    push    {r4, r5, r7, r10, r11}  @ save loop state
    push    {r8}                @ 5th arg: intensity
    mov     r3, #0              @ mirror=0
    mov     r2, r1              @ oy
    mov     r1, r0              @ ox
    mov     r0, r6              @ asset_ptr
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4          @ pop intensity
    pop     {r4, r5, r7, r10, r11}
.Lshl_gp_skip:
    add     r5, r5, #20         @ next ROM GP object (20 bytes)
    add     r7, r7, #8          @ next buf entry
    subs    r4, r4, #1
    bne     .Lshl_gp_loop
.Lshl_fg:
    @ --- FG layer ---
    ldrb    r4, [r9, #10]       @ fgCount
    ldr     r5, [r9, #20]       @ fgObjectsPtr
    cmp     r4, #0
    beq     .Lshl_done
.Lshl_fg_loop:
    ldrsh   r0, [r5]            @ obj.x
    ldrsh   r1, [r5, #2]        @ obj.y
    ldrb    r8, [r5, #5]        @ intensity
    ldr     r6, [r5, #8]        @ vector_ptr
    sub     r0, r0, r10         @ ox = x - cam_x
    sub     r1, r1, r11         @ oy = y - cam_y
    @ Cull: skip if |ox| > 180 (fully off-screen)
    mov     r12, r0
    cmp     r12, #0
    it      lt
    rsblt   r12, r12, #0        @ r12 = |ox|
    cmp     r12, #180
    bgt     .Lshl_fg_skip
    push    {r4, r5, r10, r11}  @ save loop state
    push    {r8}                @ 5th arg: intensity
    mov     r3, #0              @ mirror=0
    mov     r2, r1              @ oy
    mov     r1, r0              @ ox
    mov     r0, r6              @ asset_ptr
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4          @ pop intensity
    pop     {r4, r5, r10, r11}
.Lshl_fg_skip:
    add     r5, r5, #20         @ next FG object (20 bytes)
    subs    r4, r4, #1
    bne     .Lshl_fg_loop
.Lshl_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ pitrex_sfx_update() — advance SFX sequencer one frame
.global pitrex_sfx_update
.type pitrex_sfx_update, %function
pitrex_sfx_update:
    push    {r4, r5, r6, r7, lr}
    ldr     r0, =PSG_SFX_ACTIVE
    ldr     r0, [r0]
    cmp     r0, #0
    beq     .Lsfxu_done
    ldr     r4, =PSG_SFX_DELAY
    ldr     r0, [r4]
    cmp     r0, #0
    beq     .Lsfxu_proc
    sub     r0, r0, #1
    str     r0, [r4]
    b       .Lsfxu_done
.Lsfxu_proc:
    ldr     r5, =PSG_SFX_PTR
    ldr     r5, [r5]
    ldrb    r6, [r5, #1]                @ num_writes
    cmp     r6, #0
    beq     .Lsfxu_stop
    add     r7, r5, #2
.Lsfxu_wl:
    cmp     r6, #0
    beq     .Lsfxu_after
    ldrb    r0, [r7]
    ldrb    r1, [r7, #1]
    push    {r6, r7}
    bl      v_writePSG
    pop     {r6, r7}
    add     r7, r7, #2
    sub     r6, r6, #1
    b       .Lsfxu_wl
.Lsfxu_after:
    ldr     r0, =PSG_SFX_PTR
    str     r7, [r0]
    ldrb    r0, [r7]                    @ next event delay
    str     r0, [r4]
    b       .Lsfxu_done
.Lsfxu_stop:
    mov     r0, #10
    mov     r1, #0
    bl      v_writePSG
    ldr     r0, =PSG_SFX_ACTIVE
    mov     r1, #0
    str     r1, [r0]
.Lsfxu_done:
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_abs(r0) → |r0|
