@ pitrex_sqrt(r0=value) → r0 = integer square root
.global pitrex_sqrt
.type pitrex_sqrt, %function
pitrex_sqrt:
    vmov    s0, r0
    vcvt.f32.s32 s0, s0
    vsqrt.f32 s0, s0
    vcvt.s32.f32 s0, s0
    vmov    r0, s0
    bx      lr

@ pitrex_atan2(r0=y, r1=x) → r0 = angle 0-127
.global pitrex_atan2
.type pitrex_atan2, %function
pitrex_atan2:
    push    {r4, r5, r6, r7, lr}
    mov     r4, r0              @ r4 = y (signed)
    mov     r5, r1              @ r5 = x (signed)
    cmp     r4, #0
    it      lt
    rsblt   r6, r4, #0
    it      ge
    movge   r6, r4
    cmp     r5, #0
    it      lt
    rsblt   r7, r5, #0
    it      ge
    movge   r7, r5
    cmp     r6, #0
    cmpeq   r7, #0
    beq     .Latan2_zero
    cmp     r6, r7
    bgt     .Latan2_steep
    mov     r0, r6, asl #5      @ |y| * 32
    mov     r1, r7
    bl      __aeabi_idiv        @ r0 = ratio 0-32
    ldr     r1, =pitrex_atan_lut
    cmp     r0, #32
    movgt   r0, #32
    ldrb    r0, [r1, r0]        @ atan angle
    b       .Latan2_quad
.Latan2_steep:
    mov     r0, r7, asl #5      @ |x| * 32
    mov     r1, r6
    bl      __aeabi_idiv        @ r0 = ratio 0-32
    ldr     r1, =pitrex_atan_lut
    cmp     r0, #32
    movgt   r0, #32
    ldrb    r0, [r1, r0]
    rsb     r0, r0, #32         @ 32 - angle (complement)
.Latan2_quad:
    mov     r6, r0
    cmp     r5, #0
    blt     .Latan2_xneg
    cmp     r4, #0
    blt     .Latan2_q4
    mov     r0, r6
    b       .Latan2_done
.Latan2_q4:
    rsb     r0, r6, #128
    and     r0, r0, #127
    b       .Latan2_done
.Latan2_xneg:
    cmp     r4, #0
    blt     .Latan2_q3
    rsb     r0, r6, #64
    b       .Latan2_done
.Latan2_q3:
    add     r0, r6, #64
    and     r0, r0, #127
    b       .Latan2_done
.Latan2_zero:
    mov     r0, #0
.Latan2_done:
    pop     {r4, r5, r6, r7, pc}
    .ltorg

pitrex_atan_lut:
    .byte 0,1,2,3,4,5,6,7,8,8,9,10,11,12,12,13,14,14,15,15,16,17,17,18,18,19,19,20,20,20,21,21,22

@ pitrex_pow(r0=base, r1=exp) → r0 = base^exp (integer)
.global pitrex_pow
.type pitrex_pow, %function
pitrex_pow:
    push    {r4, r5, lr}
    mov     r4, r0      @ base
    mov     r5, r1      @ exp
    mov     r0, #1
    cmp     r5, #0
    beq     .Lpow_done
.Lpow_loop:
    mul     r0, r0, r4
    subs    r5, r5, #1
    bne     .Lpow_loop
.Lpow_done:
    pop     {r4, r5, pc}

@ pitrex_tan_impl(r0=angle 0-127) — correct tan via sin/cos LUT
.global pitrex_tan_impl
.type pitrex_tan_impl, %function
pitrex_tan_impl:
    push    {r4, r5, lr}
    and     r4, r0, #127
    ldr     r1, =pitrex_sin_lut
    ldrsb   r5, [r1, r4]   @ r5 = sin_val
    ldr     r1, =pitrex_cos_lut
    ldrsb   r4, [r1, r4]   @ r4 = cos_val
    cmp     r4, #0
    bne     .Ltani_div
    cmp     r5, #0
    movge   r0, #127
    mvnlt   r0, #126
    pop     {r4, r5, pc}
.Ltani_div:
    mov     r0, r5, asl #7
    mov     r1, r4
    bl      __aeabi_idiv
    cmp     r0, #127
    movgt   r0, #127
    mvn     r1, #126        @ r1 = -127
    cmp     r0, r1
    movlt   r0, r1
    pop     {r4, r5, pc}
    .ltorg

@ pitrex_rand() → r0 = pseudo-random 0-32767
.global pitrex_rand
.type pitrex_rand, %function
pitrex_rand:
    b       pitrex_random

@ pitrex_rand_range(r0=lo, r1=hi) → r0 = random in [lo, hi]
.global pitrex_rand_range
.type pitrex_rand_range, %function
pitrex_rand_range:
    push    {r4, r5, lr}
    mov     r4, r0              @ lo
    sub     r5, r1, r0
    add     r5, r5, #1          @ r5 = hi-lo+1 (range)
    bl      pitrex_random        @ r0 = random 0-65535
    mov     r1, r5
    bl      __aeabi_idivmod      @ r1 = r0 % r5
    add     r0, r1, r4          @ + lo
    pop     {r4, r5, pc}
    .ltorg

@ pitrex_beep(r0=period, r1=frames) — stub (no SDK PSG access)
.global pitrex_beep
.type pitrex_beep, %function
