@ pitrex_update_level() — advance GP object physics
.global pitrex_update_level
.type pitrex_update_level, %function
pitrex_update_level:
    push    {r4, r5, r6, r7, r8, r9, lr}
    ldr     r9, =LEVEL_DATA_PTR
    ldr     r9, [r9]
    cmp     r9, #0
    beq     .Lul_done
    ldr     r4, =LEVEL_GP_COUNT
    ldr     r4, [r4]            @ r4 = gpCount
    cmp     r4, #0
    beq     .Lul_done
    ldrsh   r5, [r9, #4]        @ yMin
    ldrsh   r6, [r9, #6]        @ yMax
    ldr     r7, [r9, #16]       @ gpObjectsPtr (ROM)
    ldr     r8, =LEVEL_GP_BUF   @ mutable buf
.Lul_loop:
    ldrb    r0, [r7, #6]        @ flags byte
    tst     r0, #1              @ bit0 = physics enable
    beq     .Lul_next
    ldrsh   r1, [r8]            @ buf.x
    ldrsh   r2, [r8, #2]        @ buf.y
    ldrsh   r3, [r8, #4]        @ buf.vx
    ldrsh   r12, [r8, #6]       @ buf.vy
    tst     r0, #2              @ bit1 = gravity
    beq     .Lul_nograv
    sub     r12, r12, #1        @ vy -= 1 (downward gravity)
    cmp     r12, #-32
    movlt   r12, #-32
.Lul_nograv:
    add     r1, r1, r3          @ x += vx
    add     r2, r2, r12         @ y += vy
    cmp     r2, r5
    movlt   r2, r5
    movlt   r12, #0
    cmp     r2, r6
    movgt   r2, r6
    movgt   r12, #0
    strh    r1, [r8]            @ buf.x
    strh    r2, [r8, #2]        @ buf.y
    strh    r3, [r8, #4]        @ buf.vx (unchanged)
    strh    r12, [r8, #6]       @ buf.vy
.Lul_next:
    add     r7, r7, #20         @ next ROM object (20 bytes)
    add     r8, r8, #8          @ next buf entry
    subs    r4, r4, #1
    bne     .Lul_loop
.Lul_done:
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_draw_vector_3d(r0=x, r1=y, r2=z, r3=asset_ptr) — perspective
.global pitrex_draw_vector_3d
.type pitrex_draw_vector_3d, %function
pitrex_draw_vector_3d:
    push    {r4, r5, r6, r7, lr}
    mov     r4, r0              @ x
    mov     r5, r1              @ y
    mov     r6, r2              @ z
    mov     r7, r3              @ asset_ptr
    cmp     r6, #0
    ble     .Ldv3d_done
    mov     r0, r4
    ldr     r1, =100
    mul     r0, r0, r1          @ x * 100
    mov     r1, r6
    bl      __aeabi_idiv        @ r0 = screen_x
    mov     r4, r0              @ save screen_x
    mov     r0, r5
    ldr     r1, =100
    mul     r0, r0, r1          @ y * 100
    mov     r1, r6
    bl      __aeabi_idiv        @ r0 = screen_y
    mov     r5, r0              @ save screen_y
    push    {r4, r5}            @ save screen coords
    mov     r8, #127
    push    {r8}                @ 5th arg: intensity=127
    mov     r3, #0              @ mirror=0
    mov     r2, r5              @ oy = screen_y
    mov     r1, r4              @ ox = screen_x
    mov     r0, r7              @ asset_ptr
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4          @ pop intensity
    pop     {r4, r5}            @ pop screen coords (discard)
.Ldv3d_done:
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_print_number(r0=x, r1=y, r2=value) — print decimal integer
.global pitrex_print_number
.type pitrex_print_number, %function
pitrex_print_number:
    push    {r4, r5, r6, r7, r8, r9, lr}
    mov     r4, r0          @ x
    mov     r5, r1          @ y
    mov     r6, r2          @ value
    sub     sp, sp, #8
    mov     r7, sp          @ buf ptr
    mov     r9, #0          @ is_negative = false
    cmp     r6, #0
    bge     pn_positive
    mov     r9, #1          @ is_negative = true
    mov     r0, #45         @ '-' ASCII (font renders as space-advance)
    strb    r0, [r7]
    add     r7, r7, #1
    rsb     r6, r6, #0      @ abs(r6)
pn_positive:
    @ digit 0: /1000
    ldr     r8, =1000
    mov     r0, r6
    mov     r1, r8
    bl      __aeabi_idivmod  @ r0=quot, r1=rem
    add     r0, r0, #48
    strb    r0, [r7]
    add     r7, r7, #1
    mov     r6, r1
    @ digit 1: /100
    ldr     r8, =100
    mov     r0, r6
    mov     r1, r8
    bl      __aeabi_idivmod  @ r0=quot, r1=rem
    add     r0, r0, #48
    strb    r0, [r7]
    add     r7, r7, #1
    mov     r6, r1
    @ digit 2: /10
    ldr     r8, =10
    mov     r0, r6
    mov     r1, r8
    bl      __aeabi_idivmod  @ r0=quot, r1=rem
    add     r0, r0, #48
    strb    r0, [r7]
    add     r7, r7, #1
    mov     r6, r1
    @ digit 3: ones
    add     r0, r6, #48
    strb    r0, [r7]
    add     r7, r7, #1
    mov     r0, #0
    strb    r0, [r7]
    mov     r0, #0
    mov     r1, #0
    bl      v_directMove32
    ldr     r3, =PITREX_TEXT_SIZE
    ldr     r3, [r3]
    cmp     r3, #0
    it eq
    moveq   r3, #5
    cmp     r9, #0
    beq     pn_print_str
    ldr     r12, =127
    mul     r0, r4, r12         @ x0_px = VPy_x * 127 (Rd≠Rm ✓)
    sub     r2, r5, #8          @ VPy_y - 8 (cap_height offset)
    mul     r1, r2, r12         @ y_baseline_px (Rd≠Rm ✓)
    add     r1, r1, r3, lsl #2  @ + 4*textSize
    add     r1, r1, r3, lsl #1  @ + 2*textSize → y_mid = baseline+6*ts
    add     r2, r0, r3, lsl #3  @ x1 = x0 + 8*textSize
    mov     r3, r1              @ y1 = y0 (horizontal line)
    mov     r12, #0x50
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    ldr     r3, =PITREX_TEXT_SIZE
    ldr     r3, [r3]
    cmp     r3, #0
    it eq
    moveq   r3, #5
pn_print_str:
    mov     r0, r4          @ x
    mov     r1, r5          @ y
    mov     r2, sp          @ buf ptr
    sub     r1, r1, #8          @ baseline = top - cap_height (VPy units)
    mov     r12, #127
    mul     r0, r0, r12          @ r0  = x*127
    asr     r0, r0, #7           @ r0  = x*127/128
    mul     r1, r1, r12          @ r1  = y*127
    asr     r1, r1, #7           @ r1  = y*127/128
    mov     r12, #0x50
    push    {r12}
    bl      v_printString
    add     sp, sp, #4
    add     sp, sp, #8
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_draw_anim(r0=anim_ptr, r1=ox, r2=oy, r3=mirror, [sp]=speed_mul)
.global pitrex_draw_anim
.type pitrex_draw_anim, %function
pitrex_draw_anim:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}    @ 36 bytes
    mov     r4, r0                      @ anim header ptr
    mov     r10, r1                     @ save ox
    mov     r11, r2                     @ save oy
    ldr     r8, =PITREX_ANIM_MIRROR
    strb    r3, [r8]                    @ save mirror flag
    ldr     r8, =PITREX_ANIM_SPEED
    ldr     r9, [sp, #36]               @ speed_mul (after 9 regs = 36 bytes)
    strb    r9, [r8]                    @ save speed_mul
    ldr     r5, =PITREX_ANIM_STATE_BUF
    ldrb    r6, [r5]                    @ frame_idx
    ldrb    r7, [r5, #1]                @ ticks_left (0=uninitialized)
    ldrb    r8, [r4, #2]                @ base_ref_count
    cmp     r8, #0
    beq     par_tick
    add     r9, r4, #4                  @ first base_ref word-ptr
par_base_loop:
    push    {r8, r9}
    ldr     r0, [r9]                    @ ARM ptr to vec data
    mov     r1, r10                     @ ox
    mov     r2, r11                     @ oy
    ldr     r3, =PITREX_ANIM_MIRROR
    ldrb    r3, [r3]                    @ mirror flag
    mov     r8, #127
    push    {r8}                        @ intensity=127
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4                  @ discard intensity
    pop     {r8, r9}
    add     r9, r9, #4                  @ next base_ref ptr
    subs    r8, r8, #1
    bne     par_base_loop
par_tick:
    cmp     r7, #0
    beq     par_init_frame              @ first call: init frame 0
    subs    r7, r7, #1
    bgt     par_draw                    @ still ticking: draw current frame
    ldrb    r8, [r4]                    @ frame_count
    add     r6, r6, #1
    cmp     r6, r8
    blt     par_no_wrap
    ldrb    r9, [r4, #1]                @ loop flag
    cmp     r9, #0
    beq     par_freeze
    mov     r6, #0                      @ loop: wrap to frame 0
par_no_wrap:
    strb    r6, [r5]                    @ save new frame_idx
par_init_frame:
    ldrb    r8, [r4, #3]                @ frame_table_offset
    lsl     r9, r6, #2                  @ frame_idx * 4
    add     r9, r9, r8                  @ offset to frame table entry
    ldr     r9, [r4, r9]                @ ARM ptr to frame data
    ldrb    r7, [r9]                    @ duration_ticks
    ldr     r8, =PITREX_ANIM_SPEED
    ldrb    r8, [r8]                    @ speed_mul
    cmp     r8, #1
    ble     par_speed_done
    mul     r7, r8, r7                  @ duration_ticks *= speed_mul
par_speed_done:
    cmp     r7, #0
    movle   r7, #1                      @ clamp to min 1
    strb    r7, [r5, #1]                @ save ticks_left
    b       par_draw_vecs
par_freeze:
    sub     r6, r6, #1                  @ stay on last frame
    strb    r6, [r5]
    mov     r7, #1
    strb    r7, [r5, #1]
    b       par_draw_frame
par_draw:
    strb    r7, [r5, #1]                @ save decremented ticks
par_draw_frame:
    ldrb    r8, [r4, #3]                @ frame_table_offset
    lsl     r9, r6, #2                  @ frame_idx * 4
    add     r9, r9, r8
    ldr     r9, [r4, r9]                @ ARM ptr to frame data
par_draw_vecs:
    ldrb    r8, [r9, #1]                @ vec_ref_count
    cmp     r8, #0
    beq     par_done
    add     r9, r9, #4                  @ skip duration+count+2-byte pad
    mov     r6, r8                      @ loop counter
par_vec_loop:
    push    {r6, r9}
    ldr     r0, [r9]                    @ ARM ptr to vec data
    mov     r1, r10                     @ ox
    mov     r2, r11                     @ oy
    ldr     r3, =PITREX_ANIM_MIRROR
    ldrb    r3, [r3]                    @ mirror flag
    mov     r8, #127
    push    {r8}                        @ intensity=127
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4                  @ discard intensity
    pop     {r6, r9}
    add     r9, r9, #4                  @ next vec ptr
    subs    r6, r6, #1
    bne     par_vec_loop
par_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

.bss
.balign 4
PITREX_ANIM_STATE_BUF: .space 2    @ [0]=frame_idx [1]=ticks_left
PITREX_ANIM_MIRROR: .space 1
PITREX_ANIM_SPEED: .space 1
.text

@ --- NOTE_PERIOD_TABLE: MIDI 24-107 → AY period (84 hwords) ---
.section .rodata
.balign 2
.global NOTE_PERIOD_TABLE
NOTE_PERIOD_TABLE:
    .hword 2697, 2546, 2403, 2268, 2141, 2020, 1907, 1800
    .hword 1699, 1604, 1514, 1429, 1348, 1273, 1201, 1134
    .hword 1070, 1010, 954, 900, 849, 802, 757, 714
    .hword 674, 636, 601, 567, 535, 505, 477, 450
    .hword 425, 401, 378, 357, 337, 318, 300, 283
    .hword 268, 253, 238, 225, 212, 200, 189, 179
    .hword 169, 159, 150, 142, 134, 126, 119, 113
    .hword 106, 100, 95, 89, 84, 80, 75, 71
    .hword 67, 63, 60, 56, 53, 50, 47, 45
    .hword 42, 40, 38, 35, 33, 32, 30, 28
    .hword 27, 25, 24, 22

.section .text
.align 2

@ pitrex_play_note(r0=instr_ptr, r1=channel 0-2, r2=note MIDI 24-107)
.global pitrex_play_note
.type pitrex_play_note, %function
pitrex_play_note:
    push    {r4, r5, r6, r7, lr}
    mov     r4, r0          @ r4 = instr_ptr
    mov     r5, r1          @ r5 = channel
    mov     r6, r2          @ r6 = note
    @ clamp note to 24-107
    cmp     r6, #24
    it      lt
    movlt   r6, #24
    cmp     r6, #107
    it      gt
    movgt   r6, #107
    @ r7 = &NOTE_STATE[channel]
    ldr     r0, =NOTE_STATE
    mov     r1, #32
    mul     r7, r5, r1
    add     r7, r0, r7
    @ fill channel state
    mov     r0, #1
    str     r0, [r7, #0]    @ active = 1
    ldrb    r0, [r4, #0]
    str     r0, [r7, #4]    @ frames_left = duration_frames
    str     r6, [r7, #8]    @ base_note
    str     r4, [r7, #12]   @ instr_ptr
    mov     r0, #0
    str     r0, [r7, #16]   @ arp_pos = 0
    ldrb    r0, [r4, #3]
    str     r0, [r7, #20]   @ arp_timer = arp_speed_frames
    str     r5, [r7, #28]   @ channel_id
    @ compute period from note
    sub     r0, r6, #24     @ r0 = note - 24 (index)
    lsl     r0, r0, #1      @ r0 = index * 2 (hword offset)
    ldr     r1, =NOTE_PERIOD_TABLE
    ldrh    r2, [r1, r0]    @ r2 = period
    str     r2, [r7, #24]   @ save period in state
    @ write period to PSG (reg_lo = channel*2, reg_hi = channel*2+1)
    lsl     r0, r5, #1      @ reg_lo = channel * 2
    mov     r1, r2
    and     r1, r1, #0xFF   @ period_lo
    push    {r2, r5, r7}
    bl      v_writePSG
    pop     {r2, r5, r7}
    lsl     r0, r5, #1
    add     r0, r0, #1      @ reg_hi
    mov     r1, r2
    lsr     r1, r1, #8      @ period_hi
    push    {r5, r7}
    bl      v_writePSG
    pop     {r5, r7}
    @ write volume to PSG (vol reg = channel + 8)
    ldr     r4, [r7, #12]   @ reload instr_ptr
    ldrb    r1, [r4, #1]    @ volume
    add     r0, r5, #8      @ vol reg = channel + 8
    push    {r5, r7}
    bl      v_writePSG
    pop     {r5, r7}
    @ update PSG_MIXER_SHADOW: enable tone ch, disable noise ch
    ldr     r0, =PSG_MIXER_SHADOW
    ldr     r1, [r0]
    mov     r2, #1
    lsl     r2, r2, r5      @ tone bit for channel
    bic     r1, r1, r2      @ clear = enable tone
    add     r3, r5, #3
    mov     r2, #1
    lsl     r2, r2, r3      @ noise bit
    orr     r1, r1, r2      @ set = disable noise
    str     r1, [r0]        @ update shadow
    mov     r0, #7
    push    {r5, r7}
    bl      v_writePSG
    pop     {r5, r7}
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_note_update() — advance note engine one frame (3 channels)
.global pitrex_note_update
.type pitrex_note_update, %function
pitrex_note_update:
    push    {r4, r5, r6, r7, r8, lr}
    mov     r4, #0              @ r4 = channel index
.Lpnu_loop:
    cmp     r4, #3
    bge     .Lpnu_done
    ldr     r5, =NOTE_STATE
    mov     r6, #32
    mul     r7, r4, r6
    add     r5, r5, r7      @ r5 = &NOTE_STATE[channel]
    ldr     r6, [r5, #0]    @ active
    cmp     r6, #0
    beq     .Lpnu_next
    ldr     r6, [r5, #4]    @ frames_left
    subs    r6, r6, #1
    str     r6, [r5, #4]
    bne     .Lpnu_arp
    @ note expired: mute channel
    mov     r0, #0
    str     r0, [r5, #0]    @ active = 0
    ldr     r6, [r5, #28]   @ channel_id
    add     r0, r6, #8      @ vol reg = channel_id + 8
    mov     r1, #0
    push    {r4, r5}
    bl      v_writePSG
    pop     {r4, r5}
    b       .Lpnu_next
.Lpnu_arp:
    ldr     r6, [r5, #12]   @ instr_ptr
    ldrb    r7, [r6, #2]    @ arpeggio_count
    cmp     r7, #0
    beq     .Lpnu_next
    ldr     r8, [r5, #20]   @ arp_timer
    subs    r8, r8, #1
    str     r8, [r5, #20]
    bne     .Lpnu_next
    ldrb    r8, [r6, #3]    @ arpeggio_speed_frames
    str     r8, [r5, #20]
    ldr     r8, [r5, #16]   @ arp_pos
    add     r8, r8, #1
    cmp     r8, r7
    it      ge
    movge   r8, #0
    str     r8, [r5, #16]
    ldr     r0, [r5, #8]    @ base_note
    add     r1, r6, #4      @ ptr to arpeggio_intervals[0]
    ldrsb   r1, [r1, r8]    @ signed interval at arp_pos
    add     r0, r0, r1      @ new_note
    cmp     r0, #24
    it      lt
    movlt   r0, #24
    cmp     r0, #107
    it      gt
    movgt   r0, #107
    sub     r0, r0, #24     @ index into table
    lsl     r0, r0, #1      @ hword offset
    ldr     r1, =NOTE_PERIOD_TABLE
    ldrh    r2, [r1, r0]    @ period
    ldr     r3, [r5, #28]   @ channel_id
    lsl     r0, r3, #1      @ reg_lo = channel_id * 2
    mov     r1, r2
    and     r1, r1, #0xFF
    push    {r2, r3, r4, r5}
    bl      v_writePSG
    pop     {r2, r3, r4, r5}
    lsl     r0, r3, #1
    add     r0, r0, #1      @ reg_hi
    mov     r1, r2
    lsr     r1, r1, #8
    push    {r3, r4, r5}
    bl      v_writePSG
    pop     {r3, r4, r5}
.Lpnu_next:
    add     r4, r4, #1
    b       .Lpnu_loop
.Lpnu_done:
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ pitrex_spawn_enemies(r0=data_ptr, r1=count) — fill enemy pool from ROM table
.global pitrex_spawn_enemies
.type pitrex_spawn_enemies, %function
pitrex_spawn_enemies:
    push    {r4, r5, r6, r7, r8, lr}
    mov     r4, r0          @ data_ptr
    mov     r5, r1          @ count
    ldr     r6, =PITREX_ENEMY_COUNT
    str     r5, [r6]
    ldr     r7, =PITREX_ENEMY_POOL
    cmp     r5, #0
    beq     .Lspe_done
.Lspe_loop:
    ldr     r6, [r4]        @ sprite_ptr
    str     r6, [r7]        @ pool.sprite_ptr
    ldrsh   r6, [r4, #4]    @ spawn_x
    strh    r6, [r7, #4]    @ pool.x
    strh    r6, [r7, #8]    @ pool.spawn_x
    ldrsh   r6, [r4, #6]    @ spawn_y
    strh    r6, [r7, #6]    @ pool.y
    strh    r6, [r7, #10]   @ pool.spawn_y
    ldrb    r6, [r4, #8]    @ ai_type
    strb    r6, [r7, #13]   @ pool.ai_type
    ldrb    r6, [r4, #9]    @ wp_count
    strb    r6, [r7, #15]   @ pool.wp_count
    ldrsh   r6, [r4, #12]   @ wp0_x
    strh    r6, [r7, #16]   @ pool.wp0_x
    ldrsh   r6, [r4, #14]   @ wp0_y
    strh    r6, [r7, #18]   @ pool.wp0_y
    ldrsh   r6, [r4, #16]   @ wp1_x
    strh    r6, [r7, #20]   @ pool.wp1_x
    ldrsh   r6, [r4, #18]   @ wp1_y
    strh    r6, [r7, #22]   @ pool.wp1_y
    ldrb    r6, [r4, #10]   @ mirror_on_patrol
    strb    r6, [r7, #24]   @ pool.mirror_on_patrol
    ldrb    r6, [r4, #11]   @ default_facing
    strb    r6, [r7, #25]   @ pool.default_facing
    mov     r6, #1
    strb    r6, [r7, #12]   @ pool.active = 1
    strb    r6, [r7, #26]   @ pool.dir = 1 (right, initial)
    mov     r6, #0
    strb    r6, [r7, #14]   @ pool.cur_target = 0
    str     r6, [r7, #28]   @ pool.pad (+28..+31) = 0 (also zeros anim state)
    ldrb    r8, [r4, #20]   @ ROM is_anim flag
    strb    r8, [r7, #27]   @ pool.is_anim
    cmp     r8, #0
    beq     .Lspe_novam
    ldr     r6, [r4]        @ sprite_ptr (anim header)
    ldrb    r8, [r6, #3]    @ frame_table_offset (byte3 of header)
    ldr     r8, [r6, r8]    @ frame0_ptr = anim_header[frame_table_offset]
    ldrb    r8, [r8]        @ frame0 duration_ticks
    strb    r8, [r7, #29]   @ pool.anim_ticks_left = frame0.duration
.Lspe_novam:
    add     r4, r4, #24
    add     r7, r7, #32
    subs    r5, r5, #1
    bne     .Lspe_loop
.Lspe_done:
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ pitrex_update_enemies() — advance enemy AI (patrol)
.global pitrex_update_enemies
.type pitrex_update_enemies, %function
pitrex_update_enemies:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}
    ldr     r4, =PITREX_ENEMY_COUNT
    ldr     r4, [r4]
    cmp     r4, #0
    beq     .Lpue_done
    ldr     r5, =PITREX_ENEMY_POOL
.Lpue_loop:
    ldrb    r6, [r5, #12]       @ active
    cmp     r6, #0
    beq     .Lpue_skip
    ldrb    r6, [r5, #13]       @ ai_type
    cmp     r6, #1
    bne     .Lpue_skip
    ldrb    r6, [r5, #15]       @ wp_count
    cmp     r6, #2
    blt     .Lpue_skip
    ldrb    r6, [r5, #14]       @ cur_target
    mov     r7, r5
    add     r7, r7, #16         @ &wp0_x
    lsl     r8, r6, #2          @ cur_target * 4
    add     r7, r7, r8          @ &wp[cur_target].x
    ldrsh   r8, [r7]            @ target_x
    ldrsh   r9, [r5, #4]        @ current x
    sub     r10, r8, r9         @ dx = target_x - x
    cmp     r10, #0
    beq     .Lpue_move          @ dx==0, skip dir update
    movgt   r6, #1              @ dir=right if dx>0
    movlt   r6, #0              @ dir=left  if dx<0
    strb    r6, [r5, #26]       @ pool.dir
.Lpue_move:
    mov     r7, #1              @ PATROL_SPEED
    cmp     r10, #0
    blt     .Lpue_neg
    cmp     r10, r7             @ dx <= speed?
    ble     .Lpue_snap
    add     r9, r9, r7          @ x += speed
    strh    r9, [r5, #4]
    b       .Lpue_skip
.Lpue_neg:
    rsb     r10, r10, #0        @ |dx|
    cmp     r10, r7             @ |dx| <= speed?
    ble     .Lpue_snap
    sub     r9, r9, r7          @ x -= speed
    strh    r9, [r5, #4]
    b       .Lpue_skip
.Lpue_snap:
    strh    r8, [r5, #4]        @ x = target_x
    ldrb    r6, [r5, #14]       @ cur_target
    eor     r6, r6, #1          @ toggle 0↔1
    strb    r6, [r5, #14]
.Lpue_skip:
    add     r5, r5, #32         @ next pool entry
    subs    r4, r4, #1
    bne     .Lpue_loop
.Lpue_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

@ pitrex_draw_enemies() — draw all active entries in PITREX_ENEMY_POOL
.global pitrex_draw_enemies
.type pitrex_draw_enemies, %function
pitrex_draw_enemies:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}
    ldr     r4, =PITREX_ENEMY_COUNT
    ldr     r4, [r4]
    cmp     r4, #0
    beq     .Lpde_done
    ldr     r8, =CAMERA_X
    ldr     r8, [r8]            @ cam_x
    ldr     r9, =CAMERA_Y
    ldr     r9, [r9]            @ cam_y
    ldr     r5, =PITREX_ENEMY_POOL
.Lpde_loop:
    ldrb    r6, [r5, #12]       @ active
    cmp     r6, #0
    beq     .Lpde_skip
    ldr     r6, [r5]            @ sprite_ptr
    cmp     r6, #0
    beq     .Lpde_skip
    ldrsh   r7, [r5, #4]        @ pool.x
    sub     r7, r7, r8          @ ox = x - cam_x
    ldrb    r10, [r5, #24]      @ mirror_on_patrol
    cmp     r10, #0
    beq     .Lpde_no_mirror
    ldrb    r10, [r5, #25]      @ default_facing
    ldrb    r3,  [r5, #26]      @ dir
    eor     r3, r3, r10         @ XOR
    eor     r3, r3, #1          @ XNOR → mirror
    b       .Lpde_do_draw
.Lpde_no_mirror:
    mov     r3, #0              @ mirror=0
.Lpde_do_draw:
    ldrb    r10, [r5, #27]      @ is_anim
    cmp     r10, #0
    bne     .Lpde_anim
    push    {r4, r5, r8, r9}    @ save loop state
    ldrsh   r1, [r5, #6]        @ pool.y
    sub     r1, r1, r9          @ oy = y - cam_y
    mov     r2, r1              @ oy
    mov     r1, r7              @ ox
    mov     r0, r6              @ sprite_ptr
    mov     r12, #127
    push    {r12}               @ 5th arg: intensity=127
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4          @ pop intensity
    pop     {r4, r5, r8, r9}
    b       .Lpde_skip
.Lpde_anim:
    ldrb    r11, [r5, #28]      @ anim_frame_idx
    ldrb    r12, [r5, #29]      @ anim_ticks_left
    subs    r12, r12, #1        @ ticks--; set flags
    bgt     .Lpde_anim_sf       @ ticks > 0: keep frame
    ldrb    r10, [r6]           @ frame_count (anim_header[0])
    add     r11, r11, #1
    cmp     r11, r10
    blt     .Lpde_no_wrap
    mov     r11, #0             @ wrap to 0
.Lpde_no_wrap:
    strb    r11, [r5, #28]      @ store frame_idx
    lsl     r10, r11, #2        @ frame_idx * 4
    add     r10, r10, #4        @ + 4 (header size)
    ldr     r10, [r6, r10]      @ frame_ptr
    ldrb    r12, [r10]          @ new duration_ticks
    strb    r12, [r5, #29]      @ store ticks_left
    ldr     r0, [r10, #4]       @ vec_ref
    b       .Lpde_anim_draw
.Lpde_anim_sf:
    strb    r12, [r5, #29]      @ store decremented ticks
    lsl     r10, r11, #2        @ frame_idx * 4
    add     r10, r10, #4        @ + 4 (header size)
    ldr     r10, [r6, r10]      @ frame_ptr
    ldr     r0, [r10, #4]       @ vec_ref
.Lpde_anim_draw:
    push    {r4, r5, r8, r9}    @ save loop state
    ldrsh   r1, [r5, #6]        @ pool.y
    sub     r1, r1, r9          @ oy = y - cam_y
    mov     r2, r1              @ oy
    mov     r1, r7              @ ox
    mov     r12, #127
    push    {r12}               @ intensity
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4
    pop     {r4, r5, r8, r9}
.Lpde_skip:
    add     r5, r5, #32
    subs    r4, r4, #1
    bne     .Lpde_loop
.Lpde_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

@ --- function DRAW_MAP_SCREEN ---
.align 2
.global DRAW_MAP_SCREEN
.type DRAW_MAP_SCREEN, %function
DRAW_MAP_SCREEN:
    push    {r4, r5, r6, r7, r8, lr}
    mov     r0, #80
    push    {r0}
    pop     {r0}
    bl      pitrex_set_intensity
    mov     r0, #50
    push    {r0}
    ldr     r0, =_MAP_VECTORS    @ asset 'map'
    push    {r0}
    mov     r0, #0
    push    {r0}
    mov     r0, #20
    push    {r0}
    mov     r0, #0
    push    {r0}
    pop     {r3}
    pop     {r2}
    pop     {r1}
    pop     {r0}
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4
    ldr     r1, =0x00100634    @ LOCATION_GLOW_DIRECTION
    ldr     r0, [r1]
    push    {r0}
    mov     r0, #0
    mov     r1, r0
    pop     {r0}
    cmp     r0, r1
    bne    .Lcf0
    movs    r0, #1
    b       .Lcf0e
.Lcf0:
    movs    r0, #0
.Lcf0e:
    cmp     r0, #0
    beq     if_else_0
    ldr     r1, =0x00100630    @ LOCATION_GLOW_INTENSITY
    ldr     r0, [r1]
    push    {r0}
    mov     r0, #3
    mov     r1, r0
    pop     {r0}
    add     r0, r0, r1
    ldr     r1, =0x00100630    @ LOCATION_GLOW_INTENSITY
    str     r0, [r1]
    ldr     r1, =0x00100630    @ LOCATION_GLOW_INTENSITY
    ldr     r0, [r1]
    push    {r0}
    mov     r0, #127
    mov     r1, r0
    pop     {r0}
    cmp     r0, r1
    blt    .Lcf1
    movs    r0, #1
    b       .Lcf1e
.Lcf1:
    movs    r0, #0
.Lcf1e:
    cmp     r0, #0
    beq     if_else_1
    mov     r0, #1
    ldr     r1, =0x00100634    @ LOCATION_GLOW_DIRECTION
    str     r0, [r1]
    b       if_end_1
if_else_1:
if_end_1:
    b       if_end_0
if_else_0:
    ldr     r1, =0x00100630    @ LOCATION_GLOW_INTENSITY
    ldr     r0, [r1]
    push    {r0}
    mov     r0, #3
    mov     r1, r0
    pop     {r0}
    sub     r0, r0, r1
    ldr     r1, =0x00100630    @ LOCATION_GLOW_INTENSITY
    str     r0, [r1]
    ldr     r1, =0x00100630    @ LOCATION_GLOW_INTENSITY
    ldr     r0, [r1]
    push    {r0}
    mov     r0, #80
    mov     r1, r0
    pop     {r0}
    cmp     r0, r1
    bgt    .Lcf2
    movs    r0, #1
    b       .Lcf2e
.Lcf2:
    movs    r0, #0
.Lcf2e:
    cmp     r0, #0
    beq     if_else_2
    mov     r0, #0
    ldr     r1, =0x00100634    @ LOCATION_GLOW_DIRECTION
    str     r0, [r1]
    b       if_end_2
if_else_2:
if_end_2:
if_end_0:
    ldr     r0, =-120
    push    {r0}
    ldr     r0, =-80
    push    {r0}
    ldr     r1, =0x001005F8    @ LOCATION_NAMES
    ldr     r0, [r1]
    push    {r0}
    ldr     r1, =0x0010062C    @ CURRENT_LOCATION
    ldr     r0, [r1]
    mov     r1, r0
    pop     {r0}           @ base ptr
    lsl     r1, r1, #2     @ index * 4 (ptr stride)
    add     r0, r0, r1
    ldr     r0, [r0]       @ load 32-bit string pointer
    push    {r0}
    pop     {r2}
    pop     {r1}
    pop     {r0}
    bl      pitrex_print_text
    ldr     r1, =0x001005F0    @ LOCATION_X_COORDS
    ldr     r0, [r1]
    push    {r0}
    ldr     r1, =0x0010062C    @ CURRENT_LOCATION
    ldr     r0, [r1]
    mov     r1, r0
    pop     {r0}           @ base ptr
    lsl     r1, r1, #1     @ index * 2 (i16 stride)
    add     r0, r0, r1
    ldrsh   r0, [r0]       @ sign-extend 16-bit load
    ldr     r1, =0x0010071C    @ LOC_X
    str     r0, [r1]
    ldr     r1, =0x001005F4    @ LOCATION_Y_COORDS
    ldr     r0, [r1]
    push    {r0}
    ldr     r1, =0x0010062C    @ CURRENT_LOCATION
    ldr     r0, [r1]
    mov     r1, r0
    pop     {r0}           @ base ptr
    lsl     r1, r1, #1     @ index * 2 (i16 stride)
    add     r0, r0, r1
    ldrsh   r0, [r0]       @ sign-extend 16-bit load
    ldr     r1, =0x00100720    @ LOC_Y
    str     r0, [r1]
    ldr     r1, =0x00100630    @ LOCATION_GLOW_INTENSITY
    ldr     r0, [r1]
    push    {r0}
    ldr     r0, =_LOCATION_MARKER_VECTORS    @ asset 'location_marker'
    push    {r0}
    ldr     r1, =0x00100720    @ LOC_Y
    ldr     r0, [r1]
    push    {r0}
    ldr     r1, =0x0010071C    @ LOC_X
    ldr     r0, [r1]
    push    {r0}
    mov     r0, #0
    push    {r0}
    pop     {r3}
    pop     {r2}
    pop     {r1}
    pop     {r0}
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

