@ --- function DRAW_HOOK_ROPE ---
.align 2
.global DRAW_HOOK_ROPE
.type DRAW_HOOK_ROPE, %function
DRAW_HOOK_ROPE:
    push    {r4, r5, r6, r7, r8, lr}
    ldr     r4, =0x00100738    @ save param start_x
    str     r0, [r4]
    ldr     r4, =0x0010073C    @ save param start_y
    str     r1, [r4]
    ldr     r4, =0x00100740    @ save param end_x
    str     r2, [r4]
    ldr     r4, =0x00100744    @ save param end_y
    str     r3, [r4]
    mov     r0, #127
    push    {r0}
    ldr     r1, =0x00100738    @ START_X
    ldr     r0, [r1]
    push    {r0}
    ldr     r1, =0x0010073C    @ START_Y
    ldr     r0, [r1]
    push    {r0}
    ldr     r1, =0x00100740    @ END_X
    ldr     r0, [r1]
    push    {r0}
    ldr     r1, =0x00100744    @ END_Y
    ldr     r0, [r1]
    push    {r0}
    pop     {r3}
    pop     {r2}
    pop     {r1}
    pop     {r0}
    bl      pitrex_draw_line
    add     sp, sp, #4
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ --- function READ_JOYSTICK1_STATE ---
.align 2
.global READ_JOYSTICK1_STATE
