@ vpy_uart_puts(r0=str_ptr) — write null-terminated string via UART
.type vpy_uart_puts, %function
vpy_uart_puts:
    push    {r4, lr}
    mov     r4, r0
.Lputs_loop:
    ldrb    r0, [r4], #1
    cmp     r0, #0
    beq     .Lputs_done
    bl      RPI_AuxUartWrite
    b       .Lputs_loop
.Lputs_done:
    pop     {r4, pc}

@ vpy_uart_print_int(r0=val)
.type vpy_uart_print_int, %function
vpy_uart_print_int:
    push    {r4, r5, r6, lr}
    mov     r4, r0
    cmp     r4, #0
    bge     .Lpint_pos
    mov     r0, #'-'
    bl      RPI_AuxUartWrite
    rsb     r4, r4, #0
.Lpint_pos:
    cmp     r4, #0
    bne     .Lpint_nonzero
    mov     r0, #'0'
    bl      RPI_AuxUartWrite
    b       .Lpint_done
.Lpint_nonzero:
    sub     sp, sp, #12
    mov     r6, sp
    mov     r5, #0
.Lpint_extract:
    cmp     r4, #0
    beq     .Lpint_print
    mov     r0, r4
    mov     r1, #10
    bl      __aeabi_idivmod
    add     r1, r1, #'0'
    strb    r1, [r6, r5]
    add     r5, r5, #1
    mov     r4, r0
    b       .Lpint_extract
.Lpint_print:
    sub     r5, r5, #1
.Lpint_ploop:
    cmp     r5, #0
    blt     .Lpint_cleanup
    ldrb    r0, [r6, r5]
    bl      RPI_AuxUartWrite
    sub     r5, r5, #1
    b       .Lpint_ploop
.Lpint_cleanup:
    add     sp, sp, #12
.Lpint_done:
    pop     {r4, r5, r6, pc}

@ uart_trace_xy(r0=label, r1=x, r2=y) — gated by UART_TRACE_FRAMES_LEFT
.global uart_trace_xy
.type uart_trace_xy, %function
uart_trace_xy:
    push    {r4, r5, r6, lr}
    ldr     r4, =UART_TRACE_FRAMES_LEFT
    ldr     r4, [r4]
    cmp     r4, #0
    popeq   {r4, r5, r6, pc}
    mov     r5, r1              @ save x
    mov     r6, r2              @ save y
    bl      vpy_uart_puts       @ label (r0 already)
    mov     r0, r5
    bl      vpy_uart_print_int
    mov     r0, #','
    bl      RPI_AuxUartWrite
    mov     r0, r6
    bl      vpy_uart_print_int
    ldr     r0, =.Lstr_crlf
    bl      vpy_uart_puts
    pop     {r4, r5, r6, pc}

.Lstr_start:  .asciz "VPy PiTrex starting\r\n"
.Lstr_vinit:  .asciz "vectrexinit OK\r\n"
.Lstr_frame_sep: .asciz "---\r\n"
.Lstr_dv_p:   .asciz "DV p="
.Lstr_prv:    .asciz " prv="
.Lstr_tgt:    .asciz " tgt="
.Lstr_dlt:    .asciz " dlt="
.Lstr_crlf:   .asciz "\r\n"
.Lstr_mv:     .asciz "MV "
.Lstr_dr:     .asciz "DR "
.Lstr_frame_hdr:     .asciz ">>> FRAME "
.Lstr_frame_hdr_end: .asciz " START <<<\r\n"
    .ltorg

